import React, { useReducer, useEffect, useContext, createContext } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PatientContext, PatientEntityData } from './types';
import { FHIRObservation } from '../fhir/types';
import { ChatMessage, ChatMode, GroundingSource } from '../../types';

// --- State Definitions ---

export interface PatientStoreState {
    patients: Record<string, PatientContext>;
    activePatientId: string;
    globalChatMode: ChatMode;
    isLoading: boolean;
    error: string | null;
}

// --- Actions ---

export type PatientAction =
    | { type: 'CREATE_PATIENT'; payload: { name?: string } }
    | { type: 'DELETE_PATIENT'; payload: { id: string } }
    | { type: 'SWITCH_PATIENT'; payload: { id: string } }
    | { type: 'UPDATE_PATIENT_DETAILS'; payload: { id: string; updates: Partial<PatientContext> } }
    | { type: 'UPDATE_PATIENT_ENTITIES'; payload: { id: string; entities: Partial<PatientEntityData> } }
    | { type: 'INGEST_CLINICAL_DATA'; payload: { id: string; observations: FHIRObservation[] } }
    // Chat Actions (Target Active Patient)
    | { type: 'START_REQUEST'; payload: { userMessage: ChatMessage } }
    | { type: 'ADD_RESPONSE_PLACEHOLDER' }
    | { type: 'APPEND_TO_LAST_MESSAGE'; payload: { chunk: string; sources?: GroundingSource[] } }
    | { type: 'REQUEST_FINISH' }
    | { type: 'ADD_FULL_RESPONSE'; payload: { message: ChatMessage } }
    | { type: 'UPDATE_LAST_MESSAGE_CONTENT'; payload: string }
    | { type: 'REQUEST_FAILED'; payload: string }
    | { type: 'ADD_INTERIM_MESSAGE'; payload: ChatMessage }
    // Global Actions
    | { type: 'SET_CHAT_MODE'; payload: ChatMode }
    | { type: 'SET_LOADING'; payload: boolean }
    | { type: 'RESET_ACTIVE_CHAT' }
    | { type: 'HYDRATE'; payload: PatientStoreState };

// --- Initial State Helper ---

const DEFAULT_PATIENT_ID = 'general-context';
const STORAGE_KEY = 'mediBriefPatientStore_v4';

const createDefaultPatient = (): PatientContext => ({
    id: DEFAULT_PATIENT_ID,
    name: 'General Context',
    status: 'New Admission',
    documents: [],
    chatHistory: [],
    entities: { allergies: [], codeStatus: 'Full Code', diagnosis: [] },
    clinicalData: { observations: [] },
    createdAt: Date.now(),
    lastActive: Date.now()
});

const getInitialState = (): PatientStoreState => {
    try {
        const savedState = localStorage.getItem(STORAGE_KEY);
        if (savedState) {
            const parsed = JSON.parse(savedState);
            if (parsed.patients && parsed.activePatientId) {
                // Migration checks
                Object.keys(parsed.patients).forEach(key => {
                    if (!parsed.patients[key].clinicalData) {
                        parsed.patients[key].clinicalData = { observations: [] };
                    }
                });
                return parsed;
            }
        }
    } catch (e) {
        console.warn("Failed to load patient store from localStorage, resetting.");
    }

    const defaultPatient = createDefaultPatient();
    return {
        patients: { [DEFAULT_PATIENT_ID]: defaultPatient },
        activePatientId: DEFAULT_PATIENT_ID,
        globalChatMode: ChatMode.Standard,
        isLoading: false,
        error: null
    };
};

// --- Reducer ---

const patientReducer = (state: PatientStoreState, action: PatientAction): PatientStoreState => {
    const activeId = state.activePatientId;
    const activePatient = state.patients[activeId];

    switch (action.type) {
        case 'HYDRATE':
            return action.payload;
        case 'CREATE_PATIENT': {
            const newId = uuidv4();
            const newPatient: PatientContext = {
                ...createDefaultPatient(),
                id: newId,
                name: action.payload.name || `Patient ${Object.keys(state.patients).length + 1}`,
                status: 'New Admission',
            };
            return {
                ...state,
                patients: { ...state.patients, [newId]: newPatient },
                activePatientId: newId
            };
        }
        case 'DELETE_PATIENT': {
            const targetId = action.payload.id;
            // Prevent deleting the last patient or default context if it's the only one
            if (Object.keys(state.patients).length <= 1) return state;

            const newPatients = { ...state.patients };
            delete newPatients[targetId];

            // If we deleted the active patient, switch to another one
            let newActiveId = state.activePatientId;
            if (state.activePatientId === targetId) {
                newActiveId = Object.keys(newPatients)[0];
            }

            return {
                ...state,
                patients: newPatients,
                activePatientId: newActiveId
            };
        }
        case 'SWITCH_PATIENT':
            return {
                ...state,
                activePatientId: action.payload.id
            };
        case 'UPDATE_PATIENT_DETAILS': {
            const targetId = action.payload.id;
            if (!state.patients[targetId]) return state;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...state.patients[targetId], ...action.payload.updates }
                }
            };
        }
        case 'UPDATE_PATIENT_ENTITIES': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const newEntities = { ...targetPatient.entities };
            const incoming = action.payload.entities;

            if (incoming.allergies && incoming.allergies.length > 0) {
                newEntities.allergies = [...new Set([...newEntities.allergies, ...incoming.allergies])];
            }
            if (incoming.codeStatus) newEntities.codeStatus = incoming.codeStatus;
            if (incoming.diagnosis && incoming.diagnosis.length > 0) {
                 newEntities.diagnosis = [...new Set([...newEntities.diagnosis, ...incoming.diagnosis])];
            }

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...targetPatient, entities: newEntities }
                }
            };
        }
        case 'INGEST_CLINICAL_DATA': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const existingObs = targetPatient.clinicalData?.observations || [];
            const newObs = action.payload.observations.filter(obs => 
                !existingObs.some(ex => 
                    ex.code.text === obs.code.text && 
                    ex.valueQuantity?.value === obs.valueQuantity?.value &&
                    ex.effectiveDateTime === obs.effectiveDateTime
                )
            );

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        clinicalData: {
                            ...targetPatient.clinicalData,
                            observations: [...existingObs, ...newObs]
                        }
                    }
                }
            };
        }

        // Chat Actions
        case 'START_REQUEST':
            return {
                ...state,
                isLoading: true,
                error: null,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.userMessage],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_RESPONSE_PLACEHOLDER':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, { role: 'model', content: '' }]
                    }
                }
            };
        case 'APPEND_TO_LAST_MESSAGE': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg && lastMsg.role === 'model') {
                lastMsg.content += action.payload.chunk;
                if (action.payload.sources) {
                    const existing = lastMsg.sources || [];
                    const newSources = action.payload.sources.filter(ns => 
                        !existing.some(es => 
                            (es.web?.uri && es.web.uri === ns.web?.uri) || 
                            (es.maps?.uri && es.maps.uri === ns.maps?.uri)
                        )
                    );
                    lastMsg.sources = [...existing, ...newSources];
                }
            }
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FINISH':
            return { ...state, isLoading: false };
        case 'ADD_FULL_RESPONSE':
            return {
                ...state,
                isLoading: false,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.message],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_INTERIM_MESSAGE':
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload]
                    }
                }
            };
        case 'UPDATE_LAST_MESSAGE_CONTENT': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg) lastMsg.content = action.payload;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FAILED': {
             const history = [...activePatient.chatHistory];
             const lastMsg = history[history.length - 1];
             if (lastMsg && lastMsg.role === 'model' && !lastMsg.content) {
                 lastMsg.content = `Sorry, I encountered an error.\n\n**Details:** ${action.payload}`;
             } else {
                 history.push({ role: 'model', content: `Sorry, I encountered an error.\n\n**Details:** ${action.payload}` });
             }
             return {
                ...state,
                isLoading: false,
                error: action.payload,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
             };
        }
        case 'RESET_ACTIVE_CHAT':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: [] }
                }
            };

        case 'SET_CHAT_MODE':
            return { ...state, globalChatMode: action.payload };
        case 'SET_LOADING':
            return { ...state, isLoading: action.payload };

        default:
            return state;
    }
};

// --- Context ---

interface PatientContextType {
    state: PatientStoreState;
    dispatch: React.Dispatch<PatientAction>;
    activePatient: PatientContext;
    activeMessages: ChatMessage[];
}

const PatientStoreContext = createContext<PatientContextType | undefined>(undefined);

export const PatientProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(patientReducer, getInitialState());

    // Persistence Effect
    useEffect(() => {
        try {
            const stateToSave = {
                ...state,
                patients: Object.entries(state.patients).reduce((acc, [id, p]) => {
                    const patient = p as PatientContext;
                    acc[id] = {
                        ...patient,
                        chatHistory: patient.chatHistory.map(msg => {
                            if (msg.filePreview?.base64) {
                                return { 
                                    ...msg, 
                                    filePreview: { ...msg.filePreview, base64: undefined } 
                                };
                            }
                            return msg;
                        })
                    };
                    return acc;
                }, {} as Record<string, PatientContext>)
            };
            localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
        } catch (e) {
            console.error("Failed to save patient store to localStorage", e);
        }
    }, [state]);

    const activePatient = state.patients[state.activePatientId];

    return React.createElement(PatientStoreContext.Provider, {
        value: { 
            state, 
            dispatch, 
            activePatient, 
            activeMessages: activePatient?.chatHistory || [] 
        }
    }, children);
};

export const usePatientStore = () => {
    const context = useContext(PatientStoreContext);
    if (!context) {
        throw new Error("usePatientStore must be used within a PatientProvider");
    }
    return context;
};

import React, { useState, useRef } from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import PatientCard from './PatientCard';
import AddPatientDialog from './AddPatientDialog';
import { ChevronLeftIcon, UsersIcon, DownloadIcon, ClipboardIcon, PlusIcon } from '../../components/icons';
import { useToast } from '../../components/Toast';
import { PatientContext } from '../patient-management/types';

interface SidebarRosterProps {
    isOpen: boolean;
    toggle: () => void;
}

const SidebarRoster: React.FC<SidebarRosterProps> = ({ isOpen, toggle }) => {
    const { state, dispatch } = usePatientStore();
    const { showToast } = useToast();
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const patientsList = (Object.values(state.patients) as PatientContext[]).sort((a, b) => b.lastActive - a.lastActive);

    const handleSwitch = (id: string) => {
        dispatch({ type: 'SWITCH_PATIENT', payload: { id } });
    };

    const handleDelete = (id: string, name: string) => {
        if (Object.keys(state.patients).length <= 1) {
            showToast("Cannot delete the only active patient context.", 'error');
            return;
        }

        if (confirm(`Are you sure you want to delete the context for "${name}"?\nThis action cannot be undone.`)) {
             dispatch({ type: 'DELETE_PATIENT', payload: { id } });
             showToast(`Patient context deleted`, 'info');
        }
    };

    const handleCreate = (name: string) => {
        dispatch({ type: 'CREATE_PATIENT', payload: { name } });
        setIsDialogOpen(false);
        showToast(`Patient context '${name}' initialized`, 'success');
    };

    const handleExportData = () => {
        try {
            const dataStr = JSON.stringify(state);
            const blob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `medibrief-backup-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('System backup downloaded successfully', 'success');
        } catch (e) {
            showToast('Failed to export system data', 'error');
        }
    };

    const handleImportClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const importedState = JSON.parse(event.target?.result as string);
                if (importedState && importedState.patients) {
                    dispatch({ type: 'HYDRATE', payload: importedState });
                    showToast('System data restored successfully', 'success');
                } else {
                    throw new Error("Invalid format");
                }
            } catch (error) {
                showToast('Invalid backup file format', 'error');
            }
        };
        reader.readAsText(file);
        e.target.value = ''; // Reset input
    };

    return (
        <>
            <aside 
                className={`
                    flex-shrink-0 bg-slate-50/80 dark:bg-[#080b14]/80 backdrop-blur-xl border-r border-slate-200 dark:border-white/5 transition-all duration-300 ease-in-out relative z-40
                    ${isOpen ? 'w-72' : 'w-0 opacity-0 md:opacity-100 md:w-12'}
                `}
            >
                <button
                    onClick={toggle}
                    className={`
                        absolute -right-3 top-20 z-50 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full p-1 shadow-md text-slate-500 hover:text-blue-500 transition-colors
                        ${isOpen ? 'rotate-0' : 'rotate-180'}
                    `}
                    aria-label="Toggle Roster"
                >
                    <ChevronLeftIcon className="w-3 h-3" />
                </button>

                <div className={`flex flex-col h-full overflow-hidden ${!isOpen && 'hidden md:flex'}`}>

                    {/* Header */}
                    <div className="p-4 border-b border-slate-200 dark:border-white/5 flex items-center justify-between h-16">
                        {isOpen ? (
                            <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200">
                                <UsersIcon className="w-4 h-4" />
                                <span className="font-mono text-xs font-bold uppercase tracking-widest">Active Roster</span>
                            </div>
                        ) : (
                            <div className="w-full flex justify-center">
                                <UsersIcon className="w-5 h-5 text-slate-400" />
                            </div>
                        )}

                        {isOpen && (
                            <div className="text-[10px] font-mono text-slate-400 bg-slate-200 dark:bg-white/5 px-1.5 py-0.5 rounded-sm">
                                {patientsList.length}
                            </div>
                        )}
                    </div>

                    {/* Patient List */}
                    <div className="flex-1 overflow-y-auto p-2 space-y-2">
                        {isOpen ? (
                            patientsList.map(patient => (
                                <PatientCard
                                    key={patient.id}
                                    patient={patient}
                                    isActive={patient.id === state.activePatientId}
                                    onClick={() => handleSwitch(patient.id)}
                                    onDelete={(e) => handleDelete(patient.id, patient.name)}
                                />
                            ))
                        ) : (
                            <div className="flex flex-col gap-2 items-center mt-2">
                                {patientsList.map(patient => (
                                    <button
                                        key={patient.id}
                                        onClick={() => handleSwitch(patient.id)}
                                        className={`w-8 h-8 rounded-sm flex items-center justify-center border transition-all relative group
                                            ${patient.id === state.activePatientId 
                                                ? 'bg-blue-600 border-blue-600 text-white' 
                                                : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 hover:border-blue-400'
                                            }
                                        `}
                                        title={patient.name}
                                    >
                                        <span className="text-[10px] font-bold font-mono">
                                            {patient.name.substring(0, 2).toUpperCase()}
                                        </span>
                                        <div className={`absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-white dark:border-slate-900 ${
                                            patient.status === 'Critical' ? 'bg-red-500' : 
                                            patient.status === 'Stable' ? 'bg-emerald-500' : 'bg-slate-400'
                                        }`}></div>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Footer Actions */}
                    <div className="p-3 border-t border-slate-200 dark:border-white/5 bg-slate-100/50 dark:bg-black/20 space-y-2">
                        {isOpen ? (
                            <>
                                <button 
                                    onClick={() => setIsDialogOpen(true)}
                                    className="w-full flex items-center justify-center gap-2 bg-white dark:bg-white/5 border border-slate-300 dark:border-white/10 hover:border-blue-500 text-slate-600 dark:text-slate-300 px-3 py-2 rounded-sm text-xs font-bold uppercase tracking-wide transition-all shadow-sm"
                                >
                                    <PlusIcon className="w-3.5 h-3.5" />
                                    <span>Add Patient</span>
                                </button>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={handleExportData}
                                        className="flex-1 flex items-center justify-center gap-1.5 bg-slate-200 dark:bg-white/5 border border-transparent hover:bg-slate-300 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 px-2 py-1.5 rounded-sm text-[10px] font-mono font-bold uppercase transition-colors"
                                        title="Backup Data"
                                    >
                                        <DownloadIcon className="w-3 h-3" />
                                        <span>Backup</span>
                                    </button>
                                    <button 
                                        onClick={handleImportClick}
                                        className="flex-1 flex items-center justify-center gap-1.5 bg-slate-200 dark:bg-white/5 border border-transparent hover:bg-slate-300 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 px-2 py-1.5 rounded-sm text-[10px] font-mono font-bold uppercase transition-colors"
                                        title="Restore Data"
                                    >
                                        <ClipboardIcon className="w-3 h-3" />
                                        <span>Restore</span>
                                    </button>
                                </div>
                            </>
                        ) : (
                             <button 
                                onClick={() => setIsDialogOpen(true)}
                                className="w-full flex items-center justify-center p-2 text-slate-500 hover:text-blue-500"
                                title="Add Patient"
                            >
                                <PlusIcon className="w-5 h-5" />
                            </button>
                        )}
                        <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileImport} />
                    </div>
                </div>
            </aside>

            {/* Mobile Overlay */}
            {isOpen && (
                <div 
                    className="md:hidden fixed inset-0 z-30 bg-slate-900/50 backdrop-blur-sm"
                    onClick={toggle}
                ></div>
            )}

            <AddPatientDialog 
                isOpen={isDialogOpen} 
                onClose={() => setIsDialogOpen(false)} 
                onSubmit={handleCreate} 
            />
        </>
    );
};

export default SidebarRoster;

import React, { useCallback } from 'react';
import { UploadedFile } from '../types';
import { extractEntitiesFromUpload } from '../features/clinical-analysis/entityExtractionService';
import { PatientAction } from '../features/patient-management/usePatientStore';

export const useEntityExtractor = (dispatch: React.Dispatch<PatientAction>) => {

    const triggerExtraction = useCallback(async (file: UploadedFile, patientId: string) => {
        // Run in background (fire and forget from UI perspective)
        extractEntitiesFromUpload(file).then(entities => {
            if (Object.keys(entities).length > 0) {
                dispatch({
                    type: 'UPDATE_PATIENT_ENTITIES',
                    payload: {
                        id: patientId,
                        entities
                    }
                });
            }
        });
    }, [dispatch]);

    return { triggerExtraction };
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangleIcon } from './icons';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-screen bg-slate-950 text-red-500 font-mono p-4">
            <div className="border border-red-600 bg-red-900/10 p-8 max-w-lg w-full rounded-sm technical-border relative overflow-hidden">
                <div className="absolute inset-0 bg-grid-pattern opacity-10 pointer-events-none"></div>

                <div className="flex items-center gap-4 mb-6 relative z-10">
                    <AlertTriangleIcon className="w-12 h-12 animate-pulse" />
                    <div>
                        <h1 className="text-2xl font-bold uppercase tracking-widest">System Critical Failure</h1>
                        <p className="text-xs text-red-400">Runtime Exception Detected</p>
                    </div>
                </div>

                <div className="bg-black/50 p-4 rounded-sm border border-red-900/50 mb-6 overflow-auto max-h-40 relative z-10">
                    <code className="text-xs break-all text-red-300">
                        {this.state.error?.toString()}
                    </code>
                </div>

                <button 
                    onClick={() => window.location.reload()}
                    className="w-full py-3 bg-red-600 hover:bg-red-500 text-white font-bold uppercase tracking-widest rounded-sm transition-colors relative z-10 shadow-lg shadow-red-900/20"
                >
                    Reboot System
                </button>
            </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import { ChatMessage, UploadedFile } from '../../types';
import { ClinicalDataStore } from '../fhir/types';
import { CDSSAlert } from '../cdss/types';

export type PatientStatus = 'Stable' | 'Critical' | 'Discharge Ready' | 'New Admission';

export interface PatientEntityData {
    allergies: string[];
    codeStatus: string;
    diagnosis: string[];
}

export interface PatientContext {
  id: string;
  name: string; // e.g. "Bed 4 - Unknown Male"
  mrn?: string;
  status: PatientStatus;
  documents: UploadedFile[];
  chatHistory: ChatMessage[]; 
  entities: PatientEntityData;
  clinicalData: ClinicalDataStore; // FHIR Store
  activeAlerts: CDSSAlert[]; 
  createdAt: number;
  lastActive: number;
}

import React, { useReducer, useEffect, useContext, createContext } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PatientContext, PatientEntityData } from './types';
import { FHIRObservation } from '../fhir/types';
import { ChatMessage, ChatMode, GroundingSource } from '../../types';
import { CDSSAlert } from '../cdss/types';

// --- State Definitions ---

export interface PatientStoreState {
    patients: Record<string, PatientContext>;
    activePatientId: string;
    globalChatMode: ChatMode;
    isLoading: boolean;
    error: string | null;
}

// --- Actions ---

export type PatientAction =
    | { type: 'CREATE_PATIENT'; payload: { name?: string } }
    | { type: 'DELETE_PATIENT'; payload: { id: string } }
    | { type: 'SWITCH_PATIENT'; payload: { id: string } }
    | { type: 'UPDATE_PATIENT_DETAILS'; payload: { id: string; updates: Partial<PatientContext> } }
    | { type: 'UPDATE_PATIENT_ENTITIES'; payload: { id: string; entities: Partial<PatientEntityData> } }
    | { type: 'INGEST_CLINICAL_DATA'; payload: { id: string; observations: FHIRObservation[] } }
    | { type: 'UPDATE_ALERTS'; payload: { id: string; alerts: CDSSAlert[] } }
    | { type: 'DISMISS_ALERT'; payload: { id: string; alertId: string } }
    // Chat Actions (Target Active Patient)
    | { type: 'START_REQUEST'; payload: { userMessage: ChatMessage } }
    | { type: 'ADD_RESPONSE_PLACEHOLDER' }
    | { type: 'APPEND_TO_LAST_MESSAGE'; payload: { chunk: string; sources?: GroundingSource[] } }
    | { type: 'REQUEST_FINISH' }
    | { type: 'ADD_FULL_RESPONSE'; payload: { message: ChatMessage } }
    | { type: 'UPDATE_LAST_MESSAGE_CONTENT'; payload: string }
    | { type: 'REQUEST_FAILED'; payload: string }
    | { type: 'ADD_INTERIM_MESSAGE'; payload: ChatMessage }
    // Global Actions
    | { type: 'SET_CHAT_MODE'; payload: ChatMode }
    | { type: 'SET_LOADING'; payload: boolean }
    | { type: 'RESET_ACTIVE_CHAT' }
    | { type: 'HYDRATE'; payload: PatientStoreState };

// --- Initial State Helper ---

const DEFAULT_PATIENT_ID = 'general-context';
const STORAGE_KEY = 'mediBriefPatientStore_v4';

const createDefaultPatient = (): PatientContext => ({
    id: DEFAULT_PATIENT_ID,
    name: 'General Context',
    status: 'New Admission',
    documents: [],
    chatHistory: [],
    entities: { allergies: [], codeStatus: 'Full Code', diagnosis: [] },
    clinicalData: { observations: [] },
    activeAlerts: [],
    createdAt: Date.now(),
    lastActive: Date.now()
});

const getInitialState = (): PatientStoreState => {
    try {
        const savedState = localStorage.getItem(STORAGE_KEY);
        if (savedState) {
            const parsed = JSON.parse(savedState);
            if (parsed.patients && parsed.activePatientId) {
                // Migration checks
                Object.keys(parsed.patients).forEach(key => {
                    if (!parsed.patients[key].clinicalData) {
                        parsed.patients[key].clinicalData = { observations: [] };
                    }
                    if (!parsed.patients[key].activeAlerts) {
                        parsed.patients[key].activeAlerts = [];
                    }
                });
                return parsed;
            }
        }
    } catch (e) {
        console.warn("Failed to load patient store from localStorage, resetting.");
    }

    const defaultPatient = createDefaultPatient();
    return {
        patients: { [DEFAULT_PATIENT_ID]: defaultPatient },
        activePatientId: DEFAULT_PATIENT_ID,
        globalChatMode: ChatMode.Standard,
        isLoading: false,
        error: null
    };
};

// --- Reducer ---

const patientReducer = (state: PatientStoreState, action: PatientAction): PatientStoreState => {
    const activeId = state.activePatientId;
    const activePatient = state.patients[activeId];

    switch (action.type) {
        case 'HYDRATE':
            return action.payload;
        case 'CREATE_PATIENT': {
            const newId = uuidv4();
            const newPatient: PatientContext = {
                ...createDefaultPatient(),
                id: newId,
                name: action.payload.name || `Patient ${Object.keys(state.patients).length + 1}`,
                status: 'New Admission',
            };
            return {
                ...state,
                patients: { ...state.patients, [newId]: newPatient },
                activePatientId: newId
            };
        }
        case 'DELETE_PATIENT': {
            const targetId = action.payload.id;
            // Prevent deleting the last patient or default context if it's the only one
            if (Object.keys(state.patients).length <= 1) return state;

            const newPatients = { ...state.patients };
            delete newPatients[targetId];

            // If we deleted the active patient, switch to another one
            let newActiveId = state.activePatientId;
            if (state.activePatientId === targetId) {
                newActiveId = Object.keys(newPatients)[0];
            }

            return {
                ...state,
                patients: newPatients,
                activePatientId: newActiveId
            };
        }
        case 'SWITCH_PATIENT':
            return {
                ...state,
                activePatientId: action.payload.id
            };
        case 'UPDATE_PATIENT_DETAILS': {
            const targetId = action.payload.id;
            if (!state.patients[targetId]) return state;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...state.patients[targetId], ...action.payload.updates }
                }
            };
        }
        case 'UPDATE_PATIENT_ENTITIES': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const newEntities = { ...targetPatient.entities };
            const incoming = action.payload.entities;

            if (incoming.allergies && incoming.allergies.length > 0) {
                newEntities.allergies = [...new Set([...newEntities.allergies, ...incoming.allergies])];
            }
            if (incoming.codeStatus) newEntities.codeStatus = incoming.codeStatus;
            if (incoming.diagnosis && incoming.diagnosis.length > 0) {
                 newEntities.diagnosis = [...new Set([...newEntities.diagnosis, ...incoming.diagnosis])];
            }

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...targetPatient, entities: newEntities }
                }
            };
        }
        case 'INGEST_CLINICAL_DATA': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const existingObs = targetPatient.clinicalData?.observations || [];
            const newObs = action.payload.observations.filter(obs => 
                !existingObs.some(ex => 
                    ex.code.text === obs.code.text && 
                    ex.valueQuantity?.value === obs.valueQuantity?.value &&
                    ex.effectiveDateTime === obs.effectiveDateTime
                )
            );

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        clinicalData: {
                            ...targetPatient.clinicalData,
                            observations: [...existingObs, ...newObs]
                        }
                    }
                }
            };
        }
        case 'UPDATE_ALERTS': {
             const targetId = action.payload.id;
             const targetPatient = state.patients[targetId];
             if (!targetPatient) return state;

             // Merge new alerts, avoiding duplicates by title/ruleId if possible, or just replace/append
             // For safety, we append only unique new alerts or critical ones.
             // Simpler approach: Add all, filter UI side. But let's filter duplicates here.
             const currentAlerts = targetPatient.activeAlerts || [];
             const newAlerts = action.payload.alerts.filter(na => !currentAlerts.some(ca => ca.title === na.title && ca.timestamp > Date.now() - 3600000)); // Dedup within 1 hour

             return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        activeAlerts: [...currentAlerts, ...newAlerts]
                    }
                }
             };
        }
        case 'DISMISS_ALERT': {
            const targetId = action.payload.id;
             const targetPatient = state.patients[targetId];
             if (!targetPatient) return state;

             return {
                 ...state,
                 patients: {
                     ...state.patients,
                     [targetId]: {
                         ...targetPatient,
                         activeAlerts: targetPatient.activeAlerts.filter(a => a.id !== action.payload.alertId)
                     }
                 }
             }
        }

        // Chat Actions
        case 'START_REQUEST':
            return {
                ...state,
                isLoading: true,
                error: null,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.userMessage],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_RESPONSE_PLACEHOLDER':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, { role: 'model', content: '' }]
                    }
                }
            };
        case 'APPEND_TO_LAST_MESSAGE': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg && lastMsg.role === 'model') {
                lastMsg.content += action.payload.chunk;
                if (action.payload.sources) {
                    const existing = lastMsg.sources || [];
                    const newSources = action.payload.sources.filter(ns => 
                        !existing.some(es => 
                            (es.web?.uri && es.web.uri === ns.web?.uri) || 
                            (es.maps?.uri && es.maps.uri === ns.maps?.uri)
                        )
                    );
                    lastMsg.sources = [...existing, ...newSources];
                }
            }
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FINISH':
            return { ...state, isLoading: false };
        case 'ADD_FULL_RESPONSE':
            return {
                ...state,
                isLoading: false,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.message],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_INTERIM_MESSAGE':
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload]
                    }
                }
            };
        case 'UPDATE_LAST_MESSAGE_CONTENT': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg) lastMsg.content = action.payload;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FAILED': {
             const history = [...activePatient.chatHistory];
             const lastMsg = history[history.length - 1];
             if (lastMsg && lastMsg.role === 'model' && !lastMsg.content) {
                 lastMsg.content = `Sorry, I encountered an error.\n\n**Details:** ${action.payload}`;
             } else {
                 history.push({ role: 'model', content: `Sorry, I encountered an error.\n\n**Details:** ${action.payload}` });
             }
             return {
                ...state,
                isLoading: false,
                error: action.payload,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
             };
        }
        case 'RESET_ACTIVE_CHAT':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: [] }
                }
            };

        case 'SET_CHAT_MODE':
            return { ...state, globalChatMode: action.payload };
        case 'SET_LOADING':
            return { ...state, isLoading: action.payload };

        default:
            return state;
    }
};

// --- Context ---

interface PatientContextType {
    state: PatientStoreState;
    dispatch: React.Dispatch<PatientAction>;
    activePatient: PatientContext;
    activeMessages: ChatMessage[];
}

const PatientStoreContext = createContext<PatientContextType | undefined>(undefined);

export const PatientProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(patientReducer, getInitialState());

    // Persistence Effect
    useEffect(() => {
        try {
            const stateToSave = {
                ...state,
                patients: Object.entries(state.patients).reduce((acc, [id, p]) => {
                    const patient = p as PatientContext;
                    acc[id] = {
                        ...patient,
                        chatHistory: patient.chatHistory.map(msg => {
                            if (msg.filePreview?.base64) {
                                return { 
                                    ...msg, 
                                    filePreview: { ...msg.filePreview, base64: undefined } 
                                };
                            }
                            return msg;
                        })
                    };
                    return acc;
                }, {} as Record<string, PatientContext>)
            };
            localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
        } catch (e) {
            console.error("Failed to save patient store to localStorage", e);
        }
    }, [state]);

    const activePatient = state.patients[state.activePatientId];

    return React.createElement(PatientStoreContext.Provider, {
        value: { 
            state, 
            dispatch, 
            activePatient, 
            activeMessages: activePatient?.chatHistory || [] 
        }
    }, children);
};

export const usePatientStore = () => {
    const context = useContext(PatientStoreContext);
    if (!context) {
        throw new Error("usePatientStore must be used within a PatientProvider");
    }
    return context;
};

import { GoogleGenAI } from "@google/genai";
import { v4 as uuidv4 } from 'uuid';
import { FHIRObservation } from '../fhir/types';
import { CDSSAlert } from './types';
import { CDSS_CHECK_PROMPT } from '../../constants';
import { cleanJsonOutput } from '../../utils';

export const evaluateClinicalSafety = async (observations: FHIRObservation[]): Promise<CDSSAlert[]> => {
    if (!observations || observations.length === 0) return [];

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Format observations for the model
        const obsString = observations.map(o => 
            `${o.code.text}: ${o.valueQuantity?.value} ${o.valueQuantity?.unit} (${o.effectiveDateTime})`
        ).join('\n');

        const contents = [
            {
                role: 'user',
                parts: [
                    { text: CDSS_CHECK_PROMPT },
                    { text: `\n\n**PATIENT OBSERVATIONS:**\n${obsString}` }
                ]
            }
        ];

        // Use standard model with Search capability
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: contents,
            config: {
                responseMimeType: 'application/json',
                tools: [{ googleSearch: {} }] // MANDATORY: AI must verify via search
            }
        });

        const text = response.text;
        if (!text) return [];

        const cleaned = cleanJsonOutput(text);
        const parsed = JSON.parse(cleaned);

        if (parsed.alerts && Array.isArray(parsed.alerts)) {
            return parsed.alerts.map((alert: any) => ({
                id: uuidv4(),
                ruleId: `ai-gen-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                title: alert.title || 'CLINICAL ALERT',
                description: alert.description || 'Potential protocol violation detected.',
                level: (alert.level === 'Critical' || alert.level === 'Warning') ? alert.level : 'Info',
                timestamp: Date.now(),
                triggers: Array.isArray(alert.triggers) ? alert.triggers : [],
                actions: Array.isArray(alert.actions) ? alert.actions : [{ label: 'Dismiss', type: 'dismiss' }]
            }));
        }

        return [];

    } catch (e) {
        console.warn("CDSS AI Check Failed:", e);
        return [];
    }
};

import { useCallback } from 'react';
import { usePatientStore } from '../features/patient-management/usePatientStore';
import { PatientContext } from '../features/patient-management/types';

export const useCDSS = (patient?: PatientContext) => {
    const { dispatch } = usePatientStore();

    // Read directly from patient state.
    // The "Rules Engine" is now an async AI process that pushes alerts to this state.
    const activeAlerts = patient?.activeAlerts || [];

    const dismissAlert = useCallback((alertId: string) => {
        if (patient) {
            dispatch({
                type: 'DISMISS_ALERT',
                payload: { id: patient.id, alertId }
            });
        }
    }, [dispatch, patient]);

    return {
        activeAlerts,
        dismissAlert
    };
};

import React, { useRef, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { ChatMode as ChatModeEnum, UploadedFile, ChatMessage, GroundingSource } from '../types';
import { generateResponseStream } from '../services/geminiService';
import { exportBriefingToPdf } from '../services/exportService';
import { cleanJsonOutput, isJsonBriefing, getFriendlyErrorMessage, isLabReport, parseJsonSafe } from '../utils';
import { FILE_ANALYSIS_PROMPT, BRIEFING_TRIGGERS, SHIFT_BRIEFING_PROMPT, HELP_COMMAND_RESPONSE, DRUG_ANALYSIS_PROMPT } from '../constants';
import { PatientAction } from '../features/patient-management/usePatientStore';
import { useEntityExtractor } from './useEntityExtractor';
import { FHIRObservation } from '../features/fhir/types';
import { evaluateClinicalSafety } from '../features/cdss/rulesEngine';
import { PatientContext } from '../features/patient-management/types';

interface UseChatOrchestratorProps {
    messages: ChatMessage[];
    activePatientId?: string;
    activePatient?: PatientContext; // ADDED
    chatMode: ChatModeEnum;
    dispatch: React.Dispatch<PatientAction>;
    uploadedFile: UploadedFile | null;
    setUploadedFile: (file: UploadedFile | null) => void;
    isLive: boolean;
    stopSession: () => void;
    userLocation?: { latitude: number, longitude: number };
    clearFile: () => void;
}

export const useChatOrchestrator = ({
    messages,
    activePatientId,
    activePatient, // ADDED
    chatMode,
    dispatch,
    uploadedFile,
    setUploadedFile,
    isLive,
    stopSession,
    userLocation,
    clearFile
}: UseChatOrchestratorProps) => {
    const abortControllerRef = useRef<AbortController | null>(null);
    const { triggerExtraction } = useEntityExtractor(dispatch);

    const handleStop = useCallback(() => {
        if (abortControllerRef.current) abortControllerRef.current.abort();
        dispatch({ type: 'REQUEST_FINISH' });
    }, [dispatch]);

    const handleClearChat = useCallback(() => {
        dispatch({ type: 'RESET_ACTIVE_CHAT' });
        clearFile();
    }, [dispatch, clearFile]);

    const handleSend = useCallback(async (userPrompt: string) => {
        const trimmedPrompt = userPrompt.trim();
        if (!trimmedPrompt && !uploadedFile) return;

        if (isLive) {
            stopSession();
            dispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Standard });
        }

        // --- Export Command ---
        if (trimmedPrompt.toLowerCase() === '/export') {
            const history = messages.filter(m => !isJsonBriefing(m.content));
            if (history.length === 0) {
                 dispatch({ type: 'ADD_INTERIM_MESSAGE', payload: { role: 'model', content: '⚠️ **Cannot Export:** No history available.' } });
                 return;
            }

            dispatch({ type: 'ADD_INTERIM_MESSAGE', payload: { role: 'model', content: '📥 Generating briefing for PDF export...' } });
            dispatch({ type: 'SET_LOADING', payload: true });

            abortControllerRef.current = new AbortController();
            try {
                const modeForRequest = ChatModeEnum.Standard;
                const stream = generateResponseStream(SHIFT_BRIEFING_PROMPT(), history, modeForRequest, { responseType: 'json' });
                let fullResponseText = '';
                for await (const chunk of stream) {
                    if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");
                    fullResponseText += chunk.text;
                }

                if (fullResponseText.includes("NO DATA")) throw new Error("Insufficient clinical data found.");

                const cleanedJson = cleanJsonOutput(fullResponseText);
                if (!cleanedJson.startsWith('{')) throw new Error("Invalid briefing format.");

                const parsedBriefing = JSON.parse(cleanedJson);
                if (parsedBriefing.briefingTitle && parsedBriefing.briefingTitle.includes("NO DATA")) throw new Error("Insufficient clinical data.");

                await exportBriefingToPdf(parsedBriefing);
                dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: '✅ Shift briefing PDF downloaded.' });
            } catch (e) {
                if (e.message === "Aborted") {
                     dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: '🛑 Export cancelled.' });
                } else {
                    const friendlyError = getFriendlyErrorMessage(e);
                    dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: `Sorry, PDF generation failed.\n\n**Reason:** ${friendlyError}` });
                }
            } finally {
                dispatch({ type: 'SET_LOADING', payload: false });
                abortControllerRef.current = null;
            }
            return;
        }

        // --- Help Command ---
        if (trimmedPrompt.toLowerCase() === '/help') {
             dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: '/help' } }});
             dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: HELP_COMMAND_RESPONSE } } });
             return;
        }

        // --- Standard Message & File Handling ---
        let finalApiPrompt = trimmedPrompt;
        let historyContent = trimmedPrompt;
        let fileForApi: UploadedFile | undefined = uploadedFile || undefined;
        let displayOverride = undefined;
        let modeForRequest: ChatModeEnum = chatMode === ChatModeEnum.Live ? ChatModeEnum.Standard : chatMode;
        let responseType: 'json' | 'text' = 'text';

        const isBriefingCommand = BRIEFING_TRIGGERS.some(trigger => trimmedPrompt.toLowerCase().includes(trigger)) || trimmedPrompt.toLowerCase() === '/brief';
        const isDrugCommand = trimmedPrompt.toLowerCase().startsWith('/drugs');

        if (uploadedFile) {
             // TRIGGER BACKGROUND EXTRACTION
             if (activePatientId) {
                 triggerExtraction(uploadedFile, activePatientId);
             }

             try {
                let analysisPrompt: string;
                if (uploadedFile.type === 'application/pdf') {
                    const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this medical document.`;
                    analysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name) + `\n\n${promptBase}`;
                } else if (uploadedFile.type === 'text/plain' || uploadedFile.file.name.endsWith('.txt') || uploadedFile.file.name.endsWith('.md')) {
                     const textContent = await uploadedFile.file.text();
                     const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this document.`;
                     const fullEmbeddedContent = `*** BEGIN FILE CONTENT: ${uploadedFile.file.name} ***\n${textContent}\n*** END FILE CONTENT ***\n\n${promptBase}`;
                     analysisPrompt = fullEmbeddedContent;
                     historyContent = fullEmbeddedContent;
                     displayOverride = `📄 **Uploaded ${uploadedFile.file.name}**\n\n${trimmedPrompt || "Requested analysis."}`;
                     fileForApi = undefined; 
                } else {
                    const baseAnalysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name);
                    if (!trimmedPrompt) {
                        analysisPrompt = baseAnalysisPrompt;
                        displayOverride = `Analyzing file: ${uploadedFile.file.name}`; 
                    } else {
                        analysisPrompt = `${baseAnalysisPrompt}\n\n---\n**ADDITIONAL INSTRUCTION:**\nThe user has asked: "${trimmedPrompt}".\n1. You MUST still output VALID JSON.\n2. Answer the user's question within the "visualObservations" or "note" fields.`;
                    }
                }

                finalApiPrompt = analysisPrompt;
                if (isBriefingCommand) {
                    finalApiPrompt = `${finalApiPrompt}\n\nIMPORTANT: After analyzing, ${SHIFT_BRIEFING_PROMPT()}`;
                    modeForRequest = ChatModeEnum.Standard;
                    responseType = 'json';
                    if (!displayOverride) historyContent = trimmedPrompt || "/brief (with file)";
                }
             } catch (error) {
                 dispatch({ type: 'REQUEST_FAILED', payload: getFriendlyErrorMessage(error) });
                 return;
             }
        } else if (isBriefingCommand) {
            finalApiPrompt = SHIFT_BRIEFING_PROMPT();
            historyContent = "/brief"; 
            modeForRequest = ChatModeEnum.Standard;
            responseType = 'json';
        } else if (isDrugCommand) {
            finalApiPrompt = DRUG_ANALYSIS_PROMPT(trimmedPrompt);
            modeForRequest = ChatModeEnum.Standard; 
            responseType = 'json';
        }

        if (trimmedPrompt.toLowerCase().startsWith('/patient')) modeForRequest = ChatModeEnum.Standard;

        // UI Updates
        const userMessage: ChatMessage = { role: 'user', content: historyContent };
        if (displayOverride) userMessage.displayContent = displayOverride;
        if (uploadedFile) {
            const persistenceUrl = uploadedFile.type.startsWith('image/') && uploadedFile.base64 ? `data:${uploadedFile.type};base64,${uploadedFile.base64}` : undefined;
            userMessage.filePreview = { name: uploadedFile.file.name, type: uploadedFile.type, url: persistenceUrl, base64: fileForApi ? uploadedFile.base64 : undefined };
        }

        dispatch({ type: 'START_REQUEST', payload: { userMessage } });
        dispatch({ type: 'ADD_RESPONSE_PLACEHOLDER' });
        setUploadedFile(null);

        // API Call
        abortControllerRef.current = new AbortController();
        let fullResponseBuffer = '';

        try {
            const history = [...messages];
            const stream = generateResponseStream(finalApiPrompt, history, modeForRequest, { file: fileForApi, responseType, location: userLocation });

            for await (const chunk of stream) {
                if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");

                const textChunk = chunk.text || '';
                fullResponseBuffer += textChunk;

                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                let sources: GroundingSource[] | undefined = undefined;

                if (groundingMetadata && groundingMetadata.groundingChunks) {
                    sources = groundingMetadata.groundingChunks.map(chunk => {
                        if (chunk.web) return { web: chunk.web };
                        if ((chunk as any).maps) return { maps: (chunk as any).maps };
                        return undefined;
                    }).filter(Boolean) as GroundingSource[];
                }

                dispatch({ type: 'APPEND_TO_LAST_MESSAGE', payload: { chunk: textChunk, sources } });
            }
        } catch (e) {
             if (e.message === "Aborted") {
                 dispatch({ type: 'APPEND_TO_LAST_MESSAGE', payload: { chunk: " [Stopped]" } });
            } else {
                dispatch({ type: 'REQUEST_FAILED', payload: getFriendlyErrorMessage(e) });
            }
        } finally {
            dispatch({ type: 'REQUEST_FINISH' });

            // --- AUTO-INGESTION PROTOCOL ---
            if (activePatientId && isLabReport(fullResponseBuffer)) {
                const report = parseJsonSafe<any>(fullResponseBuffer);
                if (report && report.labs) {
                    const newObs: FHIRObservation[] = report.labs.map((lab: any) => {
                         const val = parseFloat(lab.value.replace(/[^0-9.-]/g, ''));
                         const rangeMatch = lab.refRange.match(/([\d.]+)\s*-\s*([\d.]+)/);

                         if (isNaN(val)) return null;

                         const obs: FHIRObservation = {
                             resourceType: 'Observation',
                             id: uuidv4(),
                             status: 'final',
                             code: { text: lab.testName },
                             valueQuantity: { value: val, unit: lab.units },
                             effectiveDateTime: report.date && report.date !== 'Not Visible' ? new Date(report.date).toISOString() : new Date().toISOString(),
                         };

                         if (rangeMatch) {
                             obs.referenceRange = [{
                                 low: { value: parseFloat(rangeMatch[1]), unit: lab.units },
                                 high: { value: parseFloat(rangeMatch[2]), unit: lab.units }
                             }];
                         }
                         return obs;
                    }).filter(Boolean);

                    if (newObs.length > 0) {
                        dispatch({
                            type: 'INGEST_CLINICAL_DATA',
                            payload: { id: activePatientId, observations: newObs }
                        });

                        // NEW: TRIGGER AI SAFETY CHECK
                        // We combine existing + new to give full context
                        const existingObs = activePatient?.clinicalData.observations || [];
                        const combinedObs = [...existingObs, ...newObs];

                        // Run async check
                        evaluateClinicalSafety(combinedObs).then(alerts => {
                            if (alerts.length > 0) {
                                dispatch({ 
                                    type: 'UPDATE_ALERTS', 
                                    payload: { id: activePatientId, alerts } 
                                });
                            }
                        });
                    }
                }
            }

            abortControllerRef.current = null;
        }
    }, [messages, activePatientId, activePatient, chatMode, uploadedFile, isLive, stopSession, userLocation, dispatch, setUploadedFile, triggerExtraction]);

    return {
        handleSend,
        handleStop,
        handleClearChat,
        handleExportChat: useCallback(() => handleSend('/export'), [handleSend])
    };
};

import React, { useState, useCallback, useEffect } from 'react';
import { ChatMode as ChatModeEnum } from '../../types';
import Header from '../../components/Header';
import MessageList from '../../components/MessageList';
import InputBar from '../../components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import BioMetricBackground from './BioMetricBackground';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../../hooks/useChatOrchestrator';
import { DocumentTextIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';

const MainLayout: React.FC = () => {
    // --- State & Stores ---
    const { state, dispatch, activePatient, activeMessages } = usePatientStore();
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();
    const { globalChatMode, isLoading } = state;

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) setIsSidebarOpen(false);
            else setIsSidebarOpen(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: userInput } } });
        if (modelOutput) dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: modelOutput } } });
    }, [dispatch]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) dispatch({ type: 'REQUEST_FAILED', payload: liveError });
    }, [liveError, dispatch]);

    useEffect(() => {
        if (globalChatMode !== ChatModeEnum.Live && isLive) stopSession();
    }, [globalChatMode, isLive, stopSession]);

    useEffect(() => {
        if (isLive && globalChatMode !== ChatModeEnum.Live) dispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
    }, [isLive, globalChatMode, dispatch]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, 
        activePatientId: activePatient?.id,
        activePatient: activePatient, // PASS ACTIVE PATIENT FOR CONTEXT
        chatMode: globalChatMode,
        dispatch,
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    const toggleLiveSession = useCallback(() => isLive ? stopSession() : startSession(activeMessages), [isLive, stopSession, startSession, activeMessages]);

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-xl shadow-lg max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100"
            {...dragHandlers}
        >
            {/* --- ATMOSPHERIC BACKGROUND SYSTEM --- */}
            <BioMetricBackground />

            {/* Overlay for Drag & Drop */}
            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center m-4 rounded-xl animate-fade-in pointer-events-none border-2 border-blue-500/50 shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                    <div className="flex flex-col items-center text-blue-400 animate-pulse">
                        <DocumentTextIcon className="w-20 h-20 mb-6" />
                        <h2 className="text-3xl font-display font-bold tracking-tight">DATA INGESTION PROTOCOL</h2>
                        <p className="font-mono text-sm mt-2 opacity-70 uppercase tracking-widest">Release to initialize scan</p>
                    </div>
                </div>
            )}

            {/* Image Modal */}
            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}

            {/* --- LAYOUT STRUCTURE --- */}

            {/* 1. Sidebar (Left) - Glassmorphic */}
            <SidebarRoster 
                isOpen={isSidebarOpen} 
                toggle={() => setIsSidebarOpen(!isSidebarOpen)} 
            />

            {/* 2. Main Content (Right) */}
            <div className="flex-1 flex flex-col min-w-0 relative z-10">
                <Header
                    currentMode={globalChatMode}
                    onModeChange={(mode) => dispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                    onClearChat={handleClearChat}
                    onExportChat={handleExportChat}
                    onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                />

                {/* 3. Heads Up Display (HUD) */}
                {activePatient && (
                    <HeadsUpDisplay patient={activePatient} />
                )}

                {/* 4. CDSS Overlay */}
                <CDSSContainer />

                {/* CONDITIONAL RENDER: SCRIBE vs CHAT */}
                {globalChatMode === ChatModeEnum.Scribe ? (
                    <ScribeInterface />
                ) : (
                    <>
                        <MessageList 
                            messages={activeMessages} 
                            isLoading={isLoading} 
                            isLive={isLive} 
                            liveTranscript={transcript} 
                            onViewImage={handleViewImage}
                        />

                        <InputBar
                            onSend={handleSend}
                            onClearFile={clearFile}
                            setUploadedFile={setUploadedFile}
                            uploadedFile={uploadedFile}
                            isLoading={isLoading}
                            currentMode={globalChatMode}
                            toggleLiveSession={toggleLiveSession}
                            isLiveSessionActive={isLive}
                            onStop={handleStop}
                        />
                    </>
                )}
            </div>
        </div>
    );
};

export default MainLayout;

import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { ChatMode } from '../../types';

// --- State Definition ---

export interface UIState {
    isLoading: boolean;
    error: string | null;
    chatMode: ChatMode;
    // We can add other ephemeral UI states here (e.g. sidebar open) if needed later
}

// --- Actions ---

export type UIAction =
    | { type: 'SET_LOADING'; payload: boolean }
    | { type: 'SET_ERROR'; payload: string | null }
    | { type: 'SET_CHAT_MODE'; payload: ChatMode }
    | { type: 'CLEAR_ERROR' };

// --- Initial State ---

const STORAGE_KEY_MODE = 'mediBrief_chatMode_v1';

const getInitialMode = (): ChatMode => {
    try {
        const saved = sessionStorage.getItem(STORAGE_KEY_MODE);
        if (saved && Object.values(ChatMode).includes(saved as ChatMode)) {
            return saved as ChatMode;
        }
    } catch (e) {
        // ignore
    }
    return ChatMode.Standard;
};

const initialState: UIState = {
    isLoading: false,
    error: null,
    chatMode: getInitialMode(),
};

// --- Reducer ---

const uiReducer = (state: UIState, action: UIAction): UIState => {
    switch (action.type) {
        case 'SET_LOADING':
            return { ...state, isLoading: action.payload };
        case 'SET_ERROR':
            return { ...state, error: action.payload, isLoading: false };
        case 'CLEAR_ERROR':
            return { ...state, error: null };
        case 'SET_CHAT_MODE':
            return { ...state, chatMode: action.payload };
        default:
            return state;
    }
};

// --- Context ---

interface UIContextType {
    uiState: UIState;
    uiDispatch: React.Dispatch<UIAction>;
}

const UIContext = createContext<UIContextType | undefined>(undefined);

export const UIProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [uiState, uiDispatch] = useReducer(uiReducer, initialState);

    // Persistence for Chat Mode
    useEffect(() => {
        sessionStorage.setItem(STORAGE_KEY_MODE, uiState.chatMode);
    }, [uiState.chatMode]);

    return React.createElement(UIContext.Provider, {
        value: { uiState, uiDispatch }
    }, children);
};

export const useUIStore = () => {
    const context = useContext(UIContext);
    if (!context) {
        throw new Error("useUIStore must be used within a UIProvider");
    }
    return context;
};

