import React, { useReducer, useEffect, useContext, createContext } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PatientContext, PatientEntityData } from './types';
import { FHIRObservation } from '../fhir/types';
import { ChatMessage, GroundingSource } from '../../types';
import { CDSSAlert } from '../cdss/types';

// --- State Definitions ---

export interface PatientStoreState {
    patients: Record<string, PatientContext>;
    activePatientId: string;
}

// --- Actions ---

export type PatientAction =
    | { type: 'CREATE_PATIENT'; payload: { name?: string } }
    | { type: 'DELETE_PATIENT'; payload: { id: string } }
    | { type: 'SWITCH_PATIENT'; payload: { id: string } }
    | { type: 'UPDATE_PATIENT_DETAILS'; payload: { id: string; updates: Partial<PatientContext> } }
    | { type: 'UPDATE_PATIENT_ENTITIES'; payload: { id: string; entities: Partial<PatientEntityData> } }
    | { type: 'INGEST_CLINICAL_DATA'; payload: { id: string; observations: FHIRObservation[] } }
    | { type: 'UPDATE_ALERTS'; payload: { id: string; alerts: CDSSAlert[] } }
    | { type: 'DISMISS_ALERT'; payload: { id: string; alertId: string } }
    // Chat Actions (Target Active Patient) -> Now purely modifies domain history
    | { type: 'START_REQUEST'; payload: { userMessage: ChatMessage } }
    | { type: 'ADD_RESPONSE_PLACEHOLDER' }
    | { type: 'APPEND_TO_LAST_MESSAGE'; payload: { chunk: string; sources?: GroundingSource[] } }
    | { type: 'REQUEST_FINISH' }
    | { type: 'ADD_FULL_RESPONSE'; payload: { message: ChatMessage } }
    | { type: 'UPDATE_LAST_MESSAGE_CONTENT'; payload: string }
    | { type: 'REQUEST_FAILED'; payload: string }
    | { type: 'ADD_INTERIM_MESSAGE'; payload: ChatMessage }
    | { type: 'RESET_ACTIVE_CHAT' }
    | { type: 'HYDRATE'; payload: PatientStoreState };

// --- Initial State Helper ---

const DEFAULT_PATIENT_ID = 'general-context';
const STORAGE_KEY = 'mediBriefPatientStore_v4';

const createDefaultPatient = (): PatientContext => ({
    id: DEFAULT_PATIENT_ID,
    name: 'General Context',
    status: 'New Admission',
    documents: [],
    chatHistory: [],
    entities: { allergies: [], codeStatus: 'Full Code', diagnosis: [] },
    clinicalData: { observations: [] },
    activeAlerts: [],
    createdAt: Date.now(),
    lastActive: Date.now()
});

const getInitialState = (): PatientStoreState => {
    try {
        const savedState = localStorage.getItem(STORAGE_KEY);
        if (savedState) {
            const parsed = JSON.parse(savedState);
            if (parsed.patients && parsed.activePatientId) {
                // Migration checks: Ensure pure domain state
                const cleanState = {
                    patients: parsed.patients,
                    activePatientId: parsed.activePatientId
                };

                Object.keys(cleanState.patients).forEach(key => {
                    if (!cleanState.patients[key].clinicalData) {
                        cleanState.patients[key].clinicalData = { observations: [] };
                    }
                    if (!cleanState.patients[key].activeAlerts) {
                        cleanState.patients[key].activeAlerts = [];
                    }
                });
                return cleanState;
            }
        }
    } catch (e) {
        console.warn("Failed to load patient store from localStorage, resetting.");
    }

    const defaultPatient = createDefaultPatient();
    return {
        patients: { [DEFAULT_PATIENT_ID]: defaultPatient },
        activePatientId: DEFAULT_PATIENT_ID,
    };
};

// --- Reducer ---

const patientReducer = (state: PatientStoreState, action: PatientAction): PatientStoreState => {
    const activeId = state.activePatientId;
    const activePatient = state.patients[activeId];

    switch (action.type) {
        case 'HYDRATE':
            return action.payload;
        case 'CREATE_PATIENT': {
            const newId = uuidv4();
            const newPatient: PatientContext = {
                ...createDefaultPatient(),
                id: newId,
                name: action.payload.name || `Patient ${Object.keys(state.patients).length + 1}`,
                status: 'New Admission',
            };
            return {
                ...state,
                patients: { ...state.patients, [newId]: newPatient },
                activePatientId: newId
            };
        }
        case 'DELETE_PATIENT': {
            const targetId = action.payload.id;
            if (Object.keys(state.patients).length <= 1) return state;

            const newPatients = { ...state.patients };
            delete newPatients[targetId];

            let newActiveId = state.activePatientId;
            if (state.activePatientId === targetId) {
                newActiveId = Object.keys(newPatients)[0];
            }

            return {
                ...state,
                patients: newPatients,
                activePatientId: newActiveId
            };
        }
        case 'SWITCH_PATIENT':
            return {
                ...state,
                activePatientId: action.payload.id
            };
        case 'UPDATE_PATIENT_DETAILS': {
            const targetId = action.payload.id;
            if (!state.patients[targetId]) return state;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...state.patients[targetId], ...action.payload.updates }
                }
            };
        }
        case 'UPDATE_PATIENT_ENTITIES': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const newEntities = { ...targetPatient.entities };
            const incoming = action.payload.entities;

            if (incoming.allergies && incoming.allergies.length > 0) {
                newEntities.allergies = [...new Set([...newEntities.allergies, ...incoming.allergies])];
            }
            if (incoming.codeStatus) newEntities.codeStatus = incoming.codeStatus;
            if (incoming.diagnosis && incoming.diagnosis.length > 0) {
                 newEntities.diagnosis = [...new Set([...newEntities.diagnosis, ...incoming.diagnosis])];
            }

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...targetPatient, entities: newEntities }
                }
            };
        }
        case 'INGEST_CLINICAL_DATA': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const existingObs = targetPatient.clinicalData?.observations || [];
            const newObs = action.payload.observations.filter(obs => 
                !existingObs.some(ex => 
                    ex.code.text === obs.code.text && 
                    ex.valueQuantity?.value === obs.valueQuantity?.value &&
                    ex.effectiveDateTime === obs.effectiveDateTime
                )
            );

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        clinicalData: {
                            ...targetPatient.clinicalData,
                            observations: [...existingObs, ...newObs]
                        }
                    }
                }
            };
        }
        case 'UPDATE_ALERTS': {
             const targetId = action.payload.id;
             const targetPatient = state.patients[targetId];
             if (!targetPatient) return state;

             const currentAlerts = targetPatient.activeAlerts || [];
             const newAlerts = action.payload.alerts.filter(na => !currentAlerts.some(ca => ca.title === na.title && ca.timestamp > Date.now() - 3600000));

             return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        activeAlerts: [...currentAlerts, ...newAlerts]
                    }
                }
             };
        }
        case 'DISMISS_ALERT': {
            const targetId = action.payload.id;
             const targetPatient = state.patients[targetId];
             if (!targetPatient) return state;

             return {
                 ...state,
                 patients: {
                     ...state.patients,
                     [targetId]: {
                         ...targetPatient,
                         activeAlerts: targetPatient.activeAlerts.filter(a => a.id !== action.payload.alertId)
                     }
                 }
             }
        }

        // Chat Actions (Purely Domain Updates now)
        case 'START_REQUEST':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.userMessage],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_RESPONSE_PLACEHOLDER':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, { role: 'model', content: '' }]
                    }
                }
            };
        case 'APPEND_TO_LAST_MESSAGE': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg && lastMsg.role === 'model') {
                lastMsg.content += action.payload.chunk;
                if (action.payload.sources) {
                    const existing = lastMsg.sources || [];
                    const newSources = action.payload.sources.filter(ns => 
                        !existing.some(es => 
                            (es.web?.uri && es.web.uri === ns.web?.uri) || 
                            (es.maps?.uri && es.maps.uri === ns.maps?.uri)
                        )
                    );
                    lastMsg.sources = [...existing, ...newSources];
                }
            }
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FINISH':
            return state; // No-op for domain state, but kept for consistency if needed later
        case 'ADD_FULL_RESPONSE':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.message],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_INTERIM_MESSAGE':
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload]
                    }
                }
            };
        case 'UPDATE_LAST_MESSAGE_CONTENT': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg) lastMsg.content = action.payload;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FAILED': {
             // We still record the error in the chat history as a system message
             const history = [...activePatient.chatHistory];
             const lastMsg = history[history.length - 1];
             const errorMsg = `Sorry, I encountered an error.\n\n**Details:** ${action.payload}`;

             if (lastMsg && lastMsg.role === 'model' && !lastMsg.content) {
                 lastMsg.content = errorMsg;
             } else {
                 history.push({ role: 'model', content: errorMsg });
             }
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
             };
        }
        case 'RESET_ACTIVE_CHAT':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: [] }
                }
            };

        default:
            return state;
    }
};

// --- Context ---

interface PatientContextType {
    state: PatientStoreState;
    dispatch: React.Dispatch<PatientAction>;
    activePatient: PatientContext;
    activeMessages: ChatMessage[];
}

const PatientStoreContext = createContext<PatientContextType | undefined>(undefined);

export const PatientProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, dispatch] = useReducer(patientReducer, getInitialState());

    // Persistence Effect
    useEffect(() => {
        try {
            // We only save domain data now
            const stateToSave = {
                patients: Object.entries(state.patients).reduce((acc, [id, p]) => {
                    const patient = p as PatientContext;
                    acc[id] = {
                        ...patient,
                        chatHistory: patient.chatHistory.map(msg => {
                            // Strip large base64 from history before saving to avoid quota limits
                            if (msg.filePreview?.base64) {
                                return { 
                                    ...msg, 
                                    filePreview: { ...msg.filePreview, base64: undefined } 
                                };
                            }
                            return msg;
                        })
                    };
                    return acc;
                }, {} as Record<string, PatientContext>),
                activePatientId: state.activePatientId
            };
            localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
        } catch (e) {
            console.error("Failed to save patient store to localStorage", e);
        }
    }, [state]);

    const activePatient = state.patients[state.activePatientId];

    return React.createElement(PatientStoreContext.Provider, {
        value: { 
            state, 
            dispatch, 
            activePatient, 
            activeMessages: activePatient?.chatHistory || [] 
        }
    }, children);
};

export const usePatientStore = () => {
    const context = useContext(PatientStoreContext);
    if (!context) {
        throw new Error("usePatientStore must be used within a PatientProvider");
    }
    return context;
};

import React, { useRef, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { ChatMode as ChatModeEnum, UploadedFile, ChatMessage, GroundingSource } from '../types';
import { generateResponseStream } from '../services/geminiService';
import { exportBriefingToPdf } from '../services/exportService';
import { cleanJsonOutput, isJsonBriefing, getFriendlyErrorMessage, isLabReport, parseJsonSafe } from '../utils';
import { FILE_ANALYSIS_PROMPT, BRIEFING_TRIGGERS, SHIFT_BRIEFING_PROMPT, HELP_COMMAND_RESPONSE, DRUG_ANALYSIS_PROMPT } from '../constants';
import { PatientAction } from '../features/patient-management/usePatientStore';
import { useEntityExtractor } from './useEntityExtractor';
import { FHIRObservation } from '../features/fhir/types';
import { evaluateClinicalSafety } from '../features/cdss/rulesEngine';
import { PatientContext } from '../features/patient-management/types';
import { UIAction } from '../features/ui/UIContext';

interface UseChatOrchestratorProps {
    messages: ChatMessage[];
    activePatientId?: string;
    activePatient?: PatientContext;
    chatMode: ChatModeEnum;
    dispatch: React.Dispatch<PatientAction>;
    uiDispatch: React.Dispatch<UIAction>; // NEW: Orchestrates UI state
    uploadedFile: UploadedFile | null;
    setUploadedFile: (file: UploadedFile | null) => void;
    isLive: boolean;
    stopSession: () => void;
    userLocation?: { latitude: number, longitude: number };
    clearFile: () => void;
}

export const useChatOrchestrator = ({
    messages,
    activePatientId,
    activePatient,
    chatMode,
    dispatch,
    uiDispatch,
    uploadedFile,
    setUploadedFile,
    isLive,
    stopSession,
    userLocation,
    clearFile
}: UseChatOrchestratorProps) => {
    const abortControllerRef = useRef<AbortController | null>(null);
    const { triggerExtraction } = useEntityExtractor(dispatch);

    const handleStop = useCallback(() => {
        if (abortControllerRef.current) abortControllerRef.current.abort();
        dispatch({ type: 'REQUEST_FINISH' });
        uiDispatch({ type: 'SET_LOADING', payload: false });
    }, [dispatch, uiDispatch]);

    const handleClearChat = useCallback(() => {
        dispatch({ type: 'RESET_ACTIVE_CHAT' });
        clearFile();
    }, [dispatch, clearFile]);

    const handleSend = useCallback(async (userPrompt: string) => {
        const trimmedPrompt = userPrompt.trim();
        if (!trimmedPrompt && !uploadedFile) return;

        if (isLive) {
            stopSession();
            uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Standard });
        }

        // --- Export Command ---
        if (trimmedPrompt.toLowerCase() === '/export') {
            const history = messages.filter(m => !isJsonBriefing(m.content));
            if (history.length === 0) {
                 dispatch({ type: 'ADD_INTERIM_MESSAGE', payload: { role: 'model', content: '⚠️ **Cannot Export:** No history available.' } });
                 return;
            }

            dispatch({ type: 'ADD_INTERIM_MESSAGE', payload: { role: 'model', content: '📥 Generating briefing for PDF export...' } });
            uiDispatch({ type: 'SET_LOADING', payload: true });

            abortControllerRef.current = new AbortController();
            try {
                const modeForRequest = ChatModeEnum.Standard;
                const stream = generateResponseStream(SHIFT_BRIEFING_PROMPT(), history, modeForRequest, { responseType: 'json' });
                let fullResponseText = '';
                for await (const chunk of stream) {
                    if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");
                    fullResponseText += chunk.text;
                }

                if (fullResponseText.includes("NO DATA")) throw new Error("Insufficient clinical data found.");

                const cleanedJson = cleanJsonOutput(fullResponseText);
                if (!cleanedJson.startsWith('{')) throw new Error("Invalid briefing format.");

                const parsedBriefing = JSON.parse(cleanedJson);
                if (parsedBriefing.briefingTitle && parsedBriefing.briefingTitle.includes("NO DATA")) throw new Error("Insufficient clinical data.");

                await exportBriefingToPdf(parsedBriefing);
                dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: '✅ Shift briefing PDF downloaded.' });
            } catch (e) {
                if (e.message === "Aborted") {
                     dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: '🛑 Export cancelled.' });
                } else {
                    const friendlyError = getFriendlyErrorMessage(e);
                    dispatch({ type: 'UPDATE_LAST_MESSAGE_CONTENT', payload: `Sorry, PDF generation failed.\n\n**Reason:** ${friendlyError}` });
                }
            } finally {
                uiDispatch({ type: 'SET_LOADING', payload: false });
                abortControllerRef.current = null;
            }
            return;
        }

        // --- Help Command ---
        if (trimmedPrompt.toLowerCase() === '/help') {
             dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: '/help' } }});
             dispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: HELP_COMMAND_RESPONSE } } });
             return;
        }

        // --- Standard Message & File Handling ---
        let finalApiPrompt = trimmedPrompt;
        let historyContent = trimmedPrompt;
        let fileForApi: UploadedFile | undefined = uploadedFile || undefined;
        let displayOverride = undefined;
        let modeForRequest: ChatModeEnum = chatMode === ChatModeEnum.Live ? ChatModeEnum.Standard : chatMode;
        let responseType: 'json' | 'text' = 'text';

        const isBriefingCommand = BRIEFING_TRIGGERS.some(trigger => trimmedPrompt.toLowerCase().includes(trigger)) || trimmedPrompt.toLowerCase() === '/brief';
        const isDrugCommand = trimmedPrompt.toLowerCase().startsWith('/drugs');

        if (uploadedFile) {
             // TRIGGER BACKGROUND EXTRACTION
             if (activePatientId) {
                 triggerExtraction(uploadedFile, activePatientId);
             }

             try {
                let analysisPrompt: string;
                if (uploadedFile.type === 'application/pdf') {
                    const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this medical document.`;
                    analysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name) + `\n\n${promptBase}`;
                } else if (uploadedFile.type === 'text/plain' || uploadedFile.file.name.endsWith('.txt') || uploadedFile.file.name.endsWith('.md')) {
                     const textContent = await uploadedFile.file.text();
                     const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this document.`;
                     const fullEmbeddedContent = `*** BEGIN FILE CONTENT: ${uploadedFile.file.name} ***\n${textContent}\n*** END FILE CONTENT ***\n\n${promptBase}`;
                     analysisPrompt = fullEmbeddedContent;
                     historyContent = fullEmbeddedContent;
                     displayOverride = `📄 **Uploaded ${uploadedFile.file.name}**\n\n${trimmedPrompt || "Requested analysis."}`;
                     fileForApi = undefined; 
                } else {
                    const baseAnalysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name);
                    if (!trimmedPrompt) {
                        analysisPrompt = baseAnalysisPrompt;
                        displayOverride = `Analyzing file: ${uploadedFile.file.name}`; 
                    } else {
                        analysisPrompt = `${baseAnalysisPrompt}\n\n---\n**ADDITIONAL INSTRUCTION:**\nThe user has asked: "${trimmedPrompt}".\n1. You MUST still output VALID JSON.\n2. Answer the user's question within the "visualObservations" or "note" fields.`;
                    }
                }

                finalApiPrompt = analysisPrompt;
                if (isBriefingCommand) {
                    finalApiPrompt = `${finalApiPrompt}\n\nIMPORTANT: After analyzing, ${SHIFT_BRIEFING_PROMPT()}`;
                    modeForRequest = ChatModeEnum.Standard;
                    responseType = 'json';
                    if (!displayOverride) historyContent = trimmedPrompt || "/brief (with file)";
                }
             } catch (error) {
                 dispatch({ type: 'REQUEST_FAILED', payload: getFriendlyErrorMessage(error) });
                 uiDispatch({ type: 'SET_ERROR', payload: getFriendlyErrorMessage(error) });
                 return;
             }
        } else if (isBriefingCommand) {
            finalApiPrompt = SHIFT_BRIEFING_PROMPT();
            historyContent = "/brief"; 
            modeForRequest = ChatModeEnum.Standard;
            responseType = 'json';
        } else if (isDrugCommand) {
            finalApiPrompt = DRUG_ANALYSIS_PROMPT(trimmedPrompt);
            modeForRequest = ChatModeEnum.Standard; 
            responseType = 'json';
        }

        if (trimmedPrompt.toLowerCase().startsWith('/patient')) modeForRequest = ChatModeEnum.Standard;

        // UI Updates
        const userMessage: ChatMessage = { role: 'user', content: historyContent };
        if (displayOverride) userMessage.displayContent = displayOverride;
        if (uploadedFile) {
            const persistenceUrl = uploadedFile.type.startsWith('image/') && uploadedFile.base64 ? `data:${uploadedFile.type};base64,${uploadedFile.base64}` : undefined;
            userMessage.filePreview = { name: uploadedFile.file.name, type: uploadedFile.type, url: persistenceUrl, base64: fileForApi ? uploadedFile.base64 : undefined };
        }

        dispatch({ type: 'START_REQUEST', payload: { userMessage } });
        dispatch({ type: 'ADD_RESPONSE_PLACEHOLDER' });
        uiDispatch({ type: 'SET_LOADING', payload: true });
        uiDispatch({ type: 'SET_ERROR', payload: null });
        setUploadedFile(null);

        // API Call
        abortControllerRef.current = new AbortController();
        let fullResponseBuffer = '';

        try {
            const history = [...messages];
            const stream = generateResponseStream(finalApiPrompt, history, modeForRequest, { file: fileForApi, responseType, location: userLocation });

            for await (const chunk of stream) {
                if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");

                const textChunk = chunk.text || '';
                fullResponseBuffer += textChunk;

                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                let sources: GroundingSource[] | undefined = undefined;

                if (groundingMetadata && groundingMetadata.groundingChunks) {
                    sources = groundingMetadata.groundingChunks.map(chunk => {
                        if (chunk.web) return { web: chunk.web };
                        if ((chunk as any).maps) return { maps: (chunk as any).maps };
                        return undefined;
                    }).filter(Boolean) as GroundingSource[];
                }

                dispatch({ type: 'APPEND_TO_LAST_MESSAGE', payload: { chunk: textChunk, sources } });
            }
        } catch (e) {
             if (e.message === "Aborted") {
                 dispatch({ type: 'APPEND_TO_LAST_MESSAGE', payload: { chunk: " [Stopped]" } });
            } else {
                dispatch({ type: 'REQUEST_FAILED', payload: getFriendlyErrorMessage(e) });
                // We don't set global error here to avoid blocking UI, the chat message shows the error.
            }
        } finally {
            dispatch({ type: 'REQUEST_FINISH' });
            uiDispatch({ type: 'SET_LOADING', payload: false });

            // --- AUTO-INGESTION PROTOCOL ---
            if (activePatientId && isLabReport(fullResponseBuffer)) {
                const report = parseJsonSafe<any>(fullResponseBuffer);
                if (report && report.labs) {
                    const newObs: FHIRObservation[] = report.labs.map((lab: any) => {
                         const val = parseFloat(lab.value.replace(/[^0-9.-]/g, ''));
                         const rangeMatch = lab.refRange.match(/([\d.]+)\s*-\s*([\d.]+)/);

                         if (isNaN(val)) return null;

                         const obs: FHIRObservation = {
                             resourceType: 'Observation',
                             id: uuidv4(),
                             status: 'final',
                             code: { text: lab.testName },
                             valueQuantity: { value: val, unit: lab.units },
                             effectiveDateTime: report.date && report.date !== 'Not Visible' ? new Date(report.date).toISOString() : new Date().toISOString(),
                         };

                         if (rangeMatch) {
                             obs.referenceRange = [{
                                 low: { value: parseFloat(rangeMatch[1]), unit: lab.units },
                                 high: { value: parseFloat(rangeMatch[2]), unit: lab.units }
                             }];
                         }
                         return obs;
                    }).filter(Boolean);

                    if (newObs.length > 0) {
                        dispatch({
                            type: 'INGEST_CLINICAL_DATA',
                            payload: { id: activePatientId, observations: newObs }
                        });

                        // NEW: TRIGGER AI SAFETY CHECK
                        const existingObs = activePatient?.clinicalData.observations || [];
                        const combinedObs = [...existingObs, ...newObs];

                        evaluateClinicalSafety(combinedObs).then(alerts => {
                            if (alerts.length > 0) {
                                dispatch({ 
                                    type: 'UPDATE_ALERTS', 
                                    payload: { id: activePatientId, alerts } 
                                });
                            }
                        });
                    }
                }
            }

            abortControllerRef.current = null;
        }
    }, [messages, activePatientId, activePatient, chatMode, uploadedFile, isLive, stopSession, userLocation, dispatch, uiDispatch, setUploadedFile, triggerExtraction]);

    return {
        handleSend,
        handleStop,
        handleClearChat,
        handleExportChat: useCallback(() => handleSend('/export'), [handleSend])
    };
};

import React, { useState, useCallback, useEffect } from 'react';
import { ChatMode as ChatModeEnum } from '../../types';
import Header from '../../components/Header';
import MessageList from '../../components/MessageList';
import InputBar from '../../components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import BioMetricBackground from './BioMetricBackground';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../../hooks/useChatOrchestrator';
import { DocumentTextIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useUIStore } from '../ui/UIContext';

const MainLayout: React.FC = () => {
    // --- Stores ---
    const { state: patientState, dispatch: patientDispatch, activePatient, activeMessages } = usePatientStore();
    const { uiState, uiDispatch } = useUIStore();

    // --- UI State ---
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();
    const { chatMode, isLoading } = uiState;

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) setIsSidebarOpen(false);
            else setIsSidebarOpen(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) patientDispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'user', content: userInput } } });
        if (modelOutput) patientDispatch({ type: 'ADD_FULL_RESPONSE', payload: { message: { role: 'model', content: modelOutput } } });
    }, [patientDispatch]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) {
            // Log error to chat
            patientDispatch({ type: 'REQUEST_FAILED', payload: liveError });
            // Notify UI (optional, usually handled by toast/component state)
            uiDispatch({ type: 'SET_ERROR', payload: liveError });
        }
    }, [liveError, patientDispatch, uiDispatch]);

    useEffect(() => {
        if (chatMode !== ChatModeEnum.Live && isLive) stopSession();
    }, [chatMode, isLive, stopSession]);

    useEffect(() => {
        if (isLive && chatMode !== ChatModeEnum.Live) uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
    }, [isLive, chatMode, uiDispatch]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, 
        activePatientId: activePatient?.id,
        activePatient: activePatient, 
        chatMode: chatMode,
        dispatch: patientDispatch,
        uiDispatch: uiDispatch, // Pass UI dispatch
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    const toggleLiveSession = useCallback(() => isLive ? stopSession() : startSession(activeMessages), [isLive, stopSession, startSession, activeMessages]);

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-xl shadow-lg max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100"
            {...dragHandlers}
        >
            {/* --- ATMOSPHERIC BACKGROUND SYSTEM --- */}
            <BioMetricBackground />

            {/* Overlay for Drag & Drop */}
            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center m-4 rounded-xl animate-fade-in pointer-events-none border-2 border-blue-500/50 shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                    <div className="flex flex-col items-center text-blue-400 animate-pulse">
                        <DocumentTextIcon className="w-20 h-20 mb-6" />
                        <h2 className="text-3xl font-display font-bold tracking-tight">DATA INGESTION PROTOCOL</h2>
                        <p className="font-mono text-sm mt-2 opacity-70 uppercase tracking-widest">Release to initialize scan</p>
                    </div>
                </div>
            )}

            {/* Image Modal */}
            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}

            {/* --- LAYOUT STRUCTURE --- */}

            {/* 1. Sidebar (Left) - Glassmorphic */}
            <SidebarRoster 
                isOpen={isSidebarOpen} 
                toggle={() => setIsSidebarOpen(!isSidebarOpen)} 
            />

            {/* 2. Main Content (Right) */}
            <div className="flex-1 flex flex-col min-w-0 relative z-10">
                <Header
                    currentMode={chatMode}
                    onModeChange={(mode) => uiDispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                    onClearChat={handleClearChat}
                    onExportChat={handleExportChat}
                    onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                />

                {/* 3. Heads Up Display (HUD) */}
                {activePatient && (
                    <HeadsUpDisplay patient={activePatient} />
                )}

                {/* 4. CDSS Overlay */}
                <CDSSContainer />

                {/* CONDITIONAL RENDER: SCRIBE vs CHAT */}
                {chatMode === ChatModeEnum.Scribe ? (
                    <ScribeInterface />
                ) : (
                    <>
                        <MessageList 
                            messages={activeMessages} 
                            isLoading={isLoading} 
                            isLive={isLive} 
                            liveTranscript={transcript} 
                            onViewImage={handleViewImage}
                        />

                        <InputBar
                            onSend={handleSend}
                            onClearFile={clearFile}
                            setUploadedFile={setUploadedFile}
                            uploadedFile={uploadedFile}
                            isLoading={isLoading}
                            currentMode={chatMode}
                            toggleLiveSession={toggleLiveSession}
                            isLiveSessionActive={isLive}
                            onStop={handleStop}
                        />
                    </>
                )}
            </div>
        </div>
    );
};

export default MainLayout;

import React, { useReducer, useEffect, useContext, createContext } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PatientContext, PatientEntityData } from './types';
import { FHIRObservation } from '../fhir/types';
import { ChatMessage, GroundingSource } from '../../types';
import { CDSSAlert } from '../cdss/types';

// --- State Definitions ---

export interface PatientStoreState {
    patients: Record<string, PatientContext>;
    activePatientId: string;
}

// --- Actions ---

export type PatientAction =
    | { type: 'CREATE_PATIENT'; payload: { name?: string } }
    | { type: 'DELETE_PATIENT'; payload: { id: string } }
    | { type: 'SWITCH_PATIENT'; payload: { id: string } }
    | { type: 'UPDATE_PATIENT_DETAILS'; payload: { id: string; updates: Partial<PatientContext> } }
    | { type: 'UPDATE_PATIENT_ENTITIES'; payload: { id: string; entities: Partial<PatientEntityData> } }
    | { type: 'INGEST_CLINICAL_DATA'; payload: { id: string; observations: FHIRObservation[] } }
    | { type: 'UPDATE_ALERTS'; payload: { id: string; alerts: CDSSAlert[] } }
    | { type: 'DISMISS_ALERT'; payload: { id: string; alertId: string } }
    | { type: 'START_REQUEST'; payload: { userMessage: ChatMessage } }
    | { type: 'ADD_RESPONSE_PLACEHOLDER' }
    | { type: 'APPEND_TO_LAST_MESSAGE'; payload: { chunk: string; sources?: GroundingSource[] } }
    | { type: 'REQUEST_FINISH' }
    | { type: 'ADD_FULL_RESPONSE'; payload: { message: ChatMessage } }
    | { type: 'UPDATE_LAST_MESSAGE_CONTENT'; payload: string }
    | { type: 'REQUEST_FAILED'; payload: string }
    | { type: 'ADD_INTERIM_MESSAGE'; payload: ChatMessage }
    | { type: 'RESET_ACTIVE_CHAT' }
    | { type: 'HYDRATE'; payload: PatientStoreState };

// --- Initial State Helper ---

const DEFAULT_PATIENT_ID = 'general-context';
const STORAGE_KEY = 'mediBriefPatientStore_v4';

const createDefaultPatient = (): PatientContext => ({
    id: DEFAULT_PATIENT_ID,
    name: 'General Context',
    status: 'New Admission',
    documents: [],
    chatHistory: [],
    entities: { allergies: [], codeStatus: 'Full Code', diagnosis: [] },
    clinicalData: { observations: [] },
    activeAlerts: [],
    createdAt: Date.now(),
    lastActive: Date.now()
});

const getInitialState = (): PatientStoreState => {
    try {
        const savedState = localStorage.getItem(STORAGE_KEY);
        if (savedState) {
            const parsed = JSON.parse(savedState);
            if (parsed.patients && parsed.activePatientId) {
                // Migration checks
                const cleanState = {
                    patients: parsed.patients,
                    activePatientId: parsed.activePatientId
                };

                // Ensure data structure integrity
                Object.keys(cleanState.patients).forEach(key => {
                    const p = cleanState.patients[key];
                    if (!p.clinicalData) p.clinicalData = { observations: [] };
                    if (!p.activeAlerts) p.activeAlerts = [];
                });
                return cleanState;
            }
        }
    } catch (e) {
        console.warn("Failed to load patient store, resetting.");
    }

    const defaultPatient = createDefaultPatient();
    return {
        patients: { [DEFAULT_PATIENT_ID]: defaultPatient },
        activePatientId: DEFAULT_PATIENT_ID,
    };
};

// --- Reducer ---

const patientReducer = (state: PatientStoreState, action: PatientAction): PatientStoreState => {
    const activeId = state.activePatientId;
    const activePatient = state.patients[activeId];

    switch (action.type) {
        case 'HYDRATE':
            return action.payload;
        case 'CREATE_PATIENT': {
            const newId = uuidv4();
            const newPatient: PatientContext = {
                ...createDefaultPatient(),
                id: newId,
                name: action.payload.name || `Patient ${Object.keys(state.patients).length + 1}`,
                status: 'New Admission',
            };
            return {
                ...state,
                patients: { ...state.patients, [newId]: newPatient },
                activePatientId: newId
            };
        }
        case 'DELETE_PATIENT': {
            const targetId = action.payload.id;
            if (Object.keys(state.patients).length <= 1) return state;

            const newPatients = { ...state.patients };
            delete newPatients[targetId];

            let newActiveId = state.activePatientId;
            if (state.activePatientId === targetId) {
                newActiveId = Object.keys(newPatients)[0];
            }

            return {
                ...state,
                patients: newPatients,
                activePatientId: newActiveId
            };
        }
        case 'SWITCH_PATIENT':
            return {
                ...state,
                activePatientId: action.payload.id
            };
        case 'UPDATE_PATIENT_DETAILS': {
            const targetId = action.payload.id;
            if (!state.patients[targetId]) return state;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...state.patients[targetId], ...action.payload.updates }
                }
            };
        }
        case 'UPDATE_PATIENT_ENTITIES': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const newEntities = { ...targetPatient.entities };
            const incoming = action.payload.entities;

            if (incoming.allergies) {
                newEntities.allergies = [...new Set([...newEntities.allergies, ...incoming.allergies])];
            }
            if (incoming.codeStatus) newEntities.codeStatus = incoming.codeStatus;
            if (incoming.diagnosis) {
                 newEntities.diagnosis = [...new Set([...newEntities.diagnosis, ...incoming.diagnosis])];
            }

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: { ...targetPatient, entities: newEntities }
                }
            };
        }
        case 'INGEST_CLINICAL_DATA': {
            const targetId = action.payload.id;
            const targetPatient = state.patients[targetId];
            if (!targetPatient) return state;

            const existingObs = targetPatient.clinicalData?.observations || [];
            const newObs = action.payload.observations.filter(obs => 
                !existingObs.some(ex => 
                    ex.code.text === obs.code.text && 
                    ex.valueQuantity?.value === obs.valueQuantity?.value &&
                    ex.effectiveDateTime === obs.effectiveDateTime
                )
            );

            return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        clinicalData: {
                            ...targetPatient.clinicalData,
                            observations: [...existingObs, ...newObs]
                        }
                    }
                }
            };
        }
        case 'UPDATE_ALERTS': {
             const targetId = action.payload.id;
             const targetPatient = state.patients[targetId];
             if (!targetPatient) return state;

             // Merge alerts, deduping by title and recent timeframe
             const currentAlerts = targetPatient.activeAlerts || [];
             const newAlerts = action.payload.alerts.filter(na => 
                 !currentAlerts.some(ca => ca.title === na.title && ca.timestamp > Date.now() - 3600000)
             );

             return {
                ...state,
                patients: {
                    ...state.patients,
                    [targetId]: {
                        ...targetPatient,
                        activeAlerts: [...currentAlerts, ...newAlerts]
                    }
                }
             };
        }
        case 'DISMISS_ALERT': {
            const targetId = action.payload.id;
             const targetPatient = state.patients[targetId];
             if (!targetPatient) return state;

             return {
                 ...state,
                 patients: {
                     ...state.patients,
                     [targetId]: {
                         ...targetPatient,
                         activeAlerts: targetPatient.activeAlerts.filter(a => a.id !== action.payload.alertId && a.ruleId !== action.payload.alertId)
                     }
                 }
             }
        }
        case 'START_REQUEST':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.userMessage],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_RESPONSE_PLACEHOLDER':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, { role: 'model', content: '' }]
                    }
                }
            };
        case 'APPEND_TO_LAST_MESSAGE': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg && lastMsg.role === 'model') {
                lastMsg.content += action.payload.chunk;
                if (action.payload.sources) {
                    const existing = lastMsg.sources || [];
                    const newSources = action.payload.sources.filter(ns => 
                        !existing.some(es => 
                            (es.web?.uri && es.web.uri === ns.web?.uri) || 
                            (es.maps?.uri && es.maps.uri === ns.maps?.uri)
                        )
                    );
                    lastMsg.sources = [...existing, ...newSources];
                }
            }
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FINISH':
            return state; 
        case 'ADD_FULL_RESPONSE':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload.message],
                        lastActive: Date.now()
                    }
                }
            };
        case 'ADD_INTERIM_MESSAGE':
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: {
                        ...activePatient,
                        chatHistory: [...activePatient.chatHistory, action.payload]
                    }
                }
            };
        case 'UPDATE_LAST_MESSAGE_CONTENT': {
            const history = [...activePatient.chatHistory];
            const lastMsg = history[history.length - 1];
            if (lastMsg) lastMsg.content = action.payload;
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
            };
        }
        case 'REQUEST_FAILED': {
             const history = [...activePatient.chatHistory];
             const lastMsg = history[history.length - 1];
             const errorMsg = `Sorry, I encountered an error.\n\n**Details:** ${action.payload}`;
             if (lastMsg && lastMsg.role === 'model' && !lastMsg.content) {
                 lastMsg.content = errorMsg;
             } else {
                 history.push({ role: 'model', content: errorMsg });
             }
             return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: history }
                }
             };
        }
        case 'RESET_ACTIVE_CHAT':
            return {
                ...state,
                patients: {
                    ...state.patients,
                    [activeId]: { ...activePatient, chatHistory: [] }
                }
            };
        default:
            return state;
    }
};

